import javax.swing.*;import java.awt.*;
public class Main {public static void main(String[]a){SwingUtilities.invokeLater(()->{JFrame f=new JFrame("Listener Styles");JButton direct=new JButton("Direct listener"),action=new JButton("Swing Action");direct.addActionListener(e->JOptionPane.showMessageDialog(f,"Direct listener invoked"));Action reusable=new AbstractAction("Reusable Action") {public void actionPerformed(java.awt.event.ActionEvent e){JOptionPane.showMessageDialog(f,"Action invoked from "+e.getSource().getClass().getSimpleName());}};action.setAction(reusable);f.setLayout(new FlowLayout());f.add(direct);f.add(action);f.pack();f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setVisible(true);});}}
